import json

def item(w,r,ro,m,p,u,e,er,t,n):
    return {'word':w,'reading':r,'romaji':ro,'meaning':m,'pos':p,'usage':u,'example':e,'example_reading':er,'example_romaji':t[0],'translation':t[1],'nuance':n}

L={
11:('Work','Vocabulary for jobs, hiring, employment conditions, and workplace roles.',[
('仕事','しごと','shigoto','work','noun','仕事を探す','新しい仕事を探しています。','あたらしいしごとをさがしています。','Atarashii shigoto o sagashite imasu.','I am looking for a new job.','仕事 is the broad everyday word for work or a job.'),
('職業','しょくぎょう','shokugyou','occupation','noun','職業を聞く','アンケートに職業を書いてください。','あんけーとにしょくぎょうをかいてください。','Ankeeto ni shokugyou o kaite kudasai.','Please write your occupation on the questionnaire.','職業 refers to one’s occupation or profession, often in formal forms.'),
('会社','かいしゃ','kaisha','company','noun','会社に勤める','姉は大阪の会社に勤めています。','あねはおおさかのかいしゃにつとめています。','Ane wa Oosaka no kaisha ni tsutomete imasu.','My older sister works for a company in Osaka.','会社 means a company or firm; 企業 sounds more formal or corporate.'),
('社員','しゃいん','shain','employee','noun','社員として働く','社員全員に新しい規則が伝えられた。','しゃいんぜんいんにあたらしいきそくがつたえられた。','Shain zenin ni atarashii kisoku ga tsutaerareta.','The new rule was communicated to all employees.','社員 usually means a company employee, especially a regular member of staff.'),
('同僚','どうりょう','douryou','colleague','noun','同僚に相談する','困ったときは同僚に相談します。','こまったときはどうりょうにそうだんします。','Komatta toki wa douryou ni soudan shimasu.','When I have a problem, I consult a colleague.','同僚 is a coworker of roughly equal standing, unlike 上司 or 部下.'),
('上司','じょうし','joushi','supervisor','noun','上司に報告する','変更が決まったら、すぐ上司に報告してください。','へんこうがきまったら、すぐじょうしにほうこくしてください。','Henkou ga kimattara, sugu joushi ni houkoku shite kudasai.','Once the change is decided, report it to your supervisor immediately.','上司 is one’s superior or manager in an organization.'),
('部下','ぶか','buka','subordinate','noun','部下を育てる','課長は部下の意見をよく聞く。','かちょうはぶかのいけんをよくきく。','Kachou wa buka no iken o yoku kiku.','The section manager listens carefully to subordinates’ opinions.','部下 means a person under one’s supervision; it is organizational language.'),
('採用','さいよう','saiyou','hiring; adoption','noun/suru verb','社員を採用する','その会社は新卒者を十人採用した。','そのかいしゃはしんそつしゃをじゅうにんさいようした。','Sono kaisha wa shinsotsusha o juunin saiyou shita.','That company hired ten new graduates.','採用 is formal hiring or selecting; 合格 is passing an exam, not employment.'),
('面接','めんせつ','mensetsu','interview','noun/suru verb','面接を受ける','明日の面接では、経験について話します。','あしたのめんせつでは、けいけんについてはなします。','Ashita no mensetsu de wa, keiken ni tsuite hanashimasu.','In tomorrow’s interview, I will talk about my experience.','面接 commonly means a job interview, though it can also mean a formal interview.'),
('履歴書','りれきしょ','rirekisho','résumé','noun','履歴書を提出する','履歴書に写真を貼って提出した。','りれきしょにしゃしんをはってていしゅつした。','Rirekisho ni shashin o hatte teishutsu shita.','I attached a photo to my résumé and submitted it.','履歴書 is the standard Japanese résumé or career history document.'),
('募集','ぼしゅう','boshuu','recruitment; vacancy','noun/suru verb','店員を募集する','駅前の店がアルバイトを募集している。','えきまえのみせがあるばいとをぼしゅうしている。','Ekimae no mise ga arubaito o boshuu shite iru.','The shop near the station is recruiting part-time workers.','募集 is soliciting applicants, members, or entries; 応募 is applying in response.'),
('給料','きゅうりょう','kyuuryou','salary; wages','noun','給料を受け取る','給料は毎月二十五日に振り込まれます。','きゅうりょうはまいつきにじゅうごにちにふりこまれます。','Kyuuryou wa maitsuki nijuugo nichi ni furikoma remasu.','My salary is deposited on the twenty-fifth of each month.','給料 is pay received for work; 賃金 is more formal and often hourly or industrial.'),
('収入','しゅうにゅう','shuunyuu','income','noun','収入を得る','副業で少し収入を得ています。','ふくぎょうですこししゅうにゅうをえています。','Fukugyou de sukoshi shuunyuu o ete imasu.','I earn a little income from a side job.','収入 is money coming in from work, investments, or other sources.'),
('支出','ししゅつ','shishutsu','expenditure','noun','支出を減らす','家計を見直して、無駄な支出を減らした。','かけいをみなおして、むだなししゅつをへらした。','Kakei o minaoshite, muda na shishutsu o herashita.','I reviewed the household budget and cut unnecessary spending.','支出 is money spent, the counterpart of 収入.'),
('勤務','きんむ','kinmu','service; work duty','noun/suru verb','勤務時間','勤務時間は午前九時から午後五時までです。','きんむじかんはごぜんくじからごごごじまでです。','Kinmu jikan wa gozen kuji kara gogo goji made desu.','Working hours are from 9 a.m. to 5 p.m.','勤務 is formal employment or duty, often used in 勤務時間 and 勤務先.'),
('通勤','つうきん','tsuukin','commuting','noun/suru verb','通勤に時間がかかる','毎朝、電車で一時間かけて通勤する。','まいあさ、でんしゃでいちじかんかけてつうきんする。','Maiasa, densha de ichi jikan kakete tsuukin suru.','Every morning I commute by train for an hour.','通勤 specifically means commuting between home and work.'),
('残業','ざんぎょう','zangyou','overtime','noun/suru verb','残業をする','締め切り前なので、今週は残業が多い。','しめきりまえなので、こんしゅうはざんぎょうがおおい。','Shimekiri mae nanode, konshuu wa zangyou ga ooi.','Because the deadline is near, there is a lot of overtime this week.','残業 is work beyond regular hours; it does not mean simply working hard.'),
('休暇','きゅうか','kyuuka','leave; vacation','noun','休暇を取る','来週、三日間の休暇を取る予定です。','らいしゅう、みっかかんのきゅうかをとるよていです。','Raishuu, mikka kan no kyuuka o toru yotei desu.','I plan to take three days of leave next week.','休暇 is formal leave or vacation; 休み is more general and conversational.'),
('退職','たいしょく','taishoku','resignation; retirement','noun/suru verb','会社を退職する','父は六十五歳で会社を退職した。','ちちはろくじゅうごさいでかいしゃをたいしょくした。','Chichi wa rokujuugo sai de kaisha o taishoku shita.','My father retired from the company at age sixty-five.','退職 means leaving a job, whether by resignation or retirement.'),
('経験','けいけん','keiken','experience','noun/suru verb','経験を積む','海外で働いた経験が、今の仕事に役立っている。','かいがいではたらいたけいけんが、いまのしごとにやくだっている。','Kaigai de hataraita keiken ga, ima no shigoto ni yakudatte iru.','My experience working abroad helps me in my current job.','経験 is practical experience gained by doing something.'),
('資格','しかく','shikaku','qualification; license','noun','資格を取る','将来のために、簿記の資格を取った。','しょうらいのために、ぼきのしかくをとった。','Shourai no tame ni, boki no shikaku o totta.','I obtained a bookkeeping qualification for the future.','資格 is an officially recognized qualification or license.'),
('責任','せきにん','sekinin','responsibility','noun','責任を負う','担当者として、最後まで責任を負います。','たんとうしゃとして、さいごまでせきにんをおいます。','Tantousha toshite, saigo made sekinin o oimasu.','As the person in charge, I will take responsibility to the end.','責任を負う means bear responsibility; 責任がある means be responsible.'),
('担当する','たんとうする','tantou suru','be in charge of','suru verb','顧客を担当する','私は東地区の顧客を担当しています。','わたしはひがしちくのこきゃくをたんとうしています。','Watashi wa higashi chiku no kokyaku o tantou shite imasu.','I am in charge of customers in the eastern district.','担当する takes the person, area, or task one handles as its object.'),
('勤める','つとめる','tsutomeru','work for','intransitive verb','銀行に勤める','兄は地元の銀行に勤めている。','あにはじもとのぎんこうにつとめている。','Ani wa jimoto no ginkou ni tsutomete iru.','My older brother works for a local bank.','勤める uses に for the employer; 働く focuses on working itself.'),
('稼ぐ','かせぐ','kasegu','earn','transitive verb','お金を稼ぐ','大学に通いながら生活費を稼いでいる。','だいがくにかよいながらせいかつひをかせいでいる。','Daigaku ni kayo inagara seikatsuhi o kaseide iru.','I earn living expenses while attending university.','稼ぐ means earn money or time through effort.'),
('雇う','やとう','yatou','hire; employ','transitive verb','人を雇う','店は夏だけ学生を雇います。','みせはなつだけがくせいをやといます。','Mise wa natsu dake gakusei o yatoimasu.','The shop hires students only during summer.','雇う is the employer’s act of hiring; 採用 is the formal hiring process.'),
('辞める','やめる','yameru','quit; leave','transitive verb','仕事を辞める','健康のために夜勤の仕事を辞めました。','けんこうのためにやきんのしごとをやめました。','Kenkou no tame ni yakin no shigoto o yamemashita.','I quit my night-shift job for my health.','辞める means quit a job or organization; やめる can also mean stop an activity.'),
('働き方','はたらきかた','hatarakikata','way of working','noun','働き方を見直す','会社は社員の働き方を見直している。','かいしゃはしゃいんのはたらきかたをみなおしている。','Kaisha wa shain no hatarakikata o minaoshite iru.','The company is rethinking how its employees work.','働き方 covers work style, such as remote work or flexible hours.'),
('正社員','せいしゃいん','seishain','full-time employee','noun','正社員になる','卒業後は正社員として働きたい。','そつぎょうごはせいしゃいんとしてはたらきたい。','Sotsugyougo wa seishain toshite hatarakitai.','After graduating, I want to work as a full-time employee.','正社員 is a regular permanent employee, contrasted with 非正規社員.'),
('アルバイト','あるばいと','arubaito','part-time job','noun/suru verb','アルバイトをする','週末はカフェでアルバイトをしています。','しゅうまつはかふぇであるばいとをしています。','Shuumatsu wa kafe de arubaito o shite imasu.','I work part-time at a café on weekends.','アルバイト means a part-time job or the person doing it in everyday Japanese.'),
('職場','しょくば','shokuba','workplace','noun','職場の雰囲気','新しい職場の雰囲気にもすぐ慣れた。','あたらしいしょくばのふんいきにもすぐなれた。','Atarashii shokuba no funiki ni mo sugu nareta.','I quickly got used to the atmosphere at my new workplace.','職場 is the physical or organizational workplace.'),
]),
12:('Workplace','Vocabulary for meetings, business communication, projects, and office operations.',[
('会議','かいぎ','kaigi','meeting','noun/suru verb','会議を開く','午後三時から企画会議を開きます。','ごごさんじからきかくかいぎをひらきます。','Gogo sanji kara kikaku kaigi o hirakimasu.','We will hold a planning meeting from 3 p.m.','会議 is a formal meeting; 打ち合わせ often means a practical coordination meeting.'),
('議題','ぎだい','gidai','agenda item','noun','議題にする','次の会議では予算案を議題にします。','つぎのかいぎではよさんあんをぎだいにします。','Tsugi no kaigi de wa yosan an o gidai ni shimasu.','We will put the budget proposal on the agenda at the next meeting.','議題 is the topic formally discussed at a meeting.'),
('資料','しりょう','shiryou','materials; reference documents','noun','資料を配る','参加者に会議の資料を配りました。','さんかしゃにかいぎのしりょうをくばりました。','Sankasha ni kaigi no shiryou o kubarimashita.','I distributed the meeting materials to the participants.','資料 means documents or data used as reference.'),
('報告','ほうこく','houkoku','report','noun/suru verb','結果を報告する','調査の結果を部長に報告した。','ちょうさのけっかをぶちょうにほうこくした。','Chousa no kekka o buchou ni houkoku shita.','I reported the survey results to the department manager.','報告 communicates facts or results to someone responsible.'),
('連絡事項','れんらくじこう','renraku jikou','notices; matters to communicate','noun','連絡事項を伝える','朝礼で重要な連絡事項を伝えた。','ちょうれいでじゅうようなれんらくじこうをつたえた。','Chourei de juuyou na renraku jikou o tsutaeta.','I shared important notices at the morning meeting.','連絡事項 refers to specific information that needs to be passed on.'),
('提案','ていあん','teian','proposal; suggestion','noun/suru verb','改善案を提案する','経費を減らす方法を提案しました。','けいひをへらすほうほうをていあんしました。','Keihi o herasu houhou o teian shimashita.','I proposed a way to reduce expenses.','提案 is a concrete proposal, stronger and more formal than a casual suggestion.'),
('意見','いけん','iken','opinion','noun','意見を述べる','会議で率直な意見を述べました。','かいぎでそっちょくないけんをのべました。','Kaigi de socchoku na iken o nobemashita.','I stated my candid opinion at the meeting.','意見 is an opinion or view; 考え is broader and more personal.'),
('承認','しょうにん','shounin','approval','noun/suru verb','申請を承認する','部長が出張の申請を承認した。','ぶちょうがしゅっちょうのしんせいをしょうにんした。','Buchou ga shucchou no shinsei o shounin shita.','The department manager approved the business-trip request.','承認 is approval by an authority.'),
('決裁','けっさい','kessai','authorization; official approval','noun/suru verb','決裁を受ける','この契約には社長の決裁が必要です。','このけいやくにはしゃちょうのけっさいがひつようです。','Kono keiyaku ni wa shachou no kessai ga hitsuyou desu.','This contract requires the president’s authorization.','決裁 is formal internal authorization, especially for spending or contracts.'),
('企画','きかく','kikaku','plan; project','noun/suru verb','企画を立てる','春の販売企画をチームで立てています。','はるのはんばいきかくをちーむでたてています。','Haru no hanbai kikaku o chiimu de tatete imasu.','Our team is making a spring sales plan.','企画 is planning a project or the project plan itself.'),
('営業','えいぎょう','eigyou','sales; business operations','noun/suru verb','営業を担当する','彼は法人営業を担当しています。','かれはほうじんえいぎょうをたんとうしています。','Kare wa houjin eigyou o tantou shite imasu.','He handles corporate sales.','営業 covers sales activity and a business’s operation hours.'),
('取引','とりひき','torihiki','business transaction','noun/suru verb','取引を行う','海外の会社と長年取引を行っている。','かいがいのかいしゃとながねんとりひきをおこなっている。','Kaigai no kaisha to naganen torihiki o okonatte iru.','We have done business with an overseas company for many years.','取引 is a commercial transaction or ongoing business relationship.'),
('顧客','こきゃく','kokyaku','customer; client','noun','顧客の要望','顧客の要望を商品開発に生かします。','こきゃくのようぼうをしょうひんかいはつにいかします。','Kokyaku no youbou o shouhin kaihatsu ni ikashimasu.','We will use customer requests in product development.','顧客 is formal business language for a customer or client.'),
('製品','せいひん','seihin','manufactured product','noun','製品を出荷する','完成した製品を来週出荷します。','かんせいしたせいひんをらいしゅうしゅっかします。','Kansei shita seihin o raishuu shukka shimasu.','We will ship the finished products next week.','製品 emphasizes something manufactured; 商品 is a product offered for sale.'),
('納期','のうき','nouki','delivery deadline','noun','納期を守る','納期に間に合うように作業を進めます。','のうきにまにあうようにさぎょうをすすめます。','Nouki ni maniau you ni sagyou o susumemasu.','We will proceed with the work so it meets the delivery deadline.','納期 is the agreed deadline for delivering goods or work.'),
('売上','うりあげ','uriage','sales revenue','noun','売上が伸びる','夏の商品は売上が大きく伸びた。','なつのしょうひんはうりあげがおおきくのびた。','Natsu no shouhin wa uriage ga ookiku nobita.','Sales of the summer product grew substantially.','売上 is the amount of sales revenue, not net profit.'),
('利益','りえき','rieki','profit; benefit','noun','利益を上げる','会社は今年、過去最高の利益を上げた。','かいしゃはことし、かこさいこうのりえきをあげた。','Kaisha wa kotoshi, kako saikou no rieki o ageta.','The company made its highest-ever profit this year.','利益 is financial profit; it can also mean a benefit or advantage.'),
('経費','けいひ','keihi','business expense','noun','経費を削減する','不要な経費を削減する方針です。','ふようなけいひをさくげんするほうしんです。','Fuyou na keihi o sakugen suru houshin desu.','Our policy is to reduce unnecessary expenses.','経費 usually means expenses necessary for business operations.'),
('部署','ぶしょ','busho','department','noun','部署に配属される','新入社員は営業部に配属された。','しんにゅうしゃいんはえいぎょうぶにはいぞくされた。','Shinnyuu shain wa eigyoubu ni haizoku sareta.','The new employee was assigned to the sales department.','部署 is a department or section within an organization.'),
('支店','してん','shiten','branch office','noun','支店を訪問する','出張で名古屋支店を訪問します。','しゅっちょうでなごやしてんをほうもんします。','Shucchou de Nagoya shiten o houmon shimasu.','I will visit the Nagoya branch on a business trip.','支店 is a branch, contrasted with 本社 headquarters.'),
('本社','ほんしゃ','honsha','headquarters','noun','本社に確認する','詳しい条件は本社に確認してください。','くわしいじょうけんはほんしゃにかくにんしてください。','Kuwashii jouken wa honsha ni kakunin shite kudasai.','Please confirm the detailed conditions with headquarters.','本社 is the head office or headquarters.'),
('名刺','めいし','meishi','business card','noun','名刺を交換する','最初に名刺を交換してから話を始めた。','さいしょにめいしをこうかんしてからはなしをはじめた。','Saisho ni meishi o koukan shite kara hanashi o hajimeta.','We exchanged business cards before starting the conversation.','名刺 is used in professional introductions.'),
('連携','れんけい','renkei','coordination; cooperation','noun/suru verb','部署間で連携する','二つの部署が連携して問題を解決した。','ふたつのぶしょがれんけいしてもんだいをかいけつした。','Futatsu no busho ga renkei shite mondai o kaiketsu shita.','Two departments coordinated to solve the problem.','連携 emphasizes coordinated action between people or groups.'),
('共有','きょうゆう','kyouyuu','sharing; shared use','noun/suru verb','情報を共有する','チームで最新の情報を共有しましょう。','ちーむでさいしんのじょうほうをきょうゆうしましょう。','Chiimu de saishin no jouhou o kyouyuu shimashou.','Let’s share the latest information within the team.','共有する means make information or resources shared.'),
('確認する','かくにんする','kakunin suru','confirm; check','suru verb','日程を確認する','送る前に宛先をもう一度確認してください。','おくるまえにあてさきをもういちどかくにんしてください。','Okuru mae ni atesaki o mou ichido kakunin shite kudasai.','Please check the destination address once more before sending it.','確認する checks that information or a condition is correct.'),
('任せる','まかせる','makaseru','entrust; leave to','transitive verb','仕事を任せる','この作業は経験のある田中さんに任せます。','このさぎょうはけいけんのあるたなかさんにまかせます。','Kono sagyou wa keiken no aru Tanaka-san ni makasemasu.','I will entrust this task to the experienced Ms. Tanaka.','任せる takes the person entrusted with a task as に.'),
('間に合わせる','まにあわせる','maniawaseru','make in time','transitive verb','納期に間に合わせる','人を増やして、納期に間に合わせた。','ひとをふやして、のうきにまにあわせた。','Hito o fuyashite, nouki ni maniawaseta.','We added staff and got it finished by the deadline.','間に合わせる is transitive; 間に合う means something is in time.'),
('進捗','しんちょく','shinchoku','progress','noun','進捗を報告する','毎週月曜日にプロジェクトの進捗を報告します。','まいしゅうげつようびにぷろじぇくとのしんちょくをほうこくします。','Maishuu getsuyoubi ni purojekuto no shinchoku o houkoku shimasu.','We report the project’s progress every Monday.','進捗 is progress toward completion, common in project management.'),
('効率','こうりつ','kouritsu','efficiency','noun','効率を上げる','作業の順番を変えると効率が上がります。','さぎょうのじゅんばんをかえるとこうりつがあがります。','Sagyou no junban o kaeru to kouritsu ga agarimasu.','Changing the order of the tasks will improve efficiency.','効率 is the ratio of results to time or effort.'),
('丁寧','ていねい','teinei','careful; polite','な-adjective','丁寧に説明する','担当者が手続きの流れを丁寧に説明した。','たんとうしゃがてつづきのながれをていねいにせつめいした。','Tantousha ga tetsuzuki no nagare o teinei ni setsumei shita.','The person in charge carefully explained the procedure.','丁寧 means careful in work and polite in manner.'),
]),
13:('Communication','Vocabulary for conversations, requests, disagreement, tone, and implied meaning.',[
('会話','かいわ','kaiwa','conversation','noun/suru verb','会話を続ける','初対面でも自然に会話を続けられた。','しょたいめんでもしぜんにかいわをつづけられた。','Shotaimen demo shizen ni kaiwa o tsuzukerareta.','I was able to keep the conversation going naturally even with someone I had just met.','会話 is an interactive conversation; 話 is a broader word for talk or story.'),
('連絡先','れんらくさき','renrakusaki','contact details','noun','連絡先を交換する','後で連絡できるように連絡先を交換した。','あとでれんらくできるようにれんらくさきをこうかんした。','Ato de renraku dekiru you ni renrakusaki o koukan shita.','We exchanged contact details so we could get in touch later.','連絡先 means an address, phone number, or other way to contact someone.'),
('伝言','でんごん','dengon','message','noun','伝言を頼む','戻ったら、部長に電話をくれと伝言してください。','もどったら、ぶちょうにでんわをくれとでんごんしてください。','Modottara, buchou ni denwa o kure to dengon shite kudasai.','When he returns, please leave a message telling him to call me.','伝言 is a message passed on when the intended person is absent.'),
('返事','へんじ','henji','reply; answer','noun/suru verb','返事をする','メールを読んだら、今日中に返事をしてください。','めーるをよんだら、きょうじゅうにへんじをしてください。','Meeru o yondara, kyoujuu ni henji o shite kudasai.','After reading the email, please reply today.','返事 is an everyday reply or answer to a call, question, or message.'),
('返信','へんしん','henshin','written reply','noun/suru verb','メールに返信する','確認したら、このメールに返信してください。','かくにんしたら、このめーるにへんしんしてください。','Kakunin shitara, kono meeru ni henshin shite kudasai.','After checking, please reply to this email.','返信 is specifically replying to a written message, especially email.'),
('説明する','せつめいする','setsumei suru','explain','suru verb','理由を説明する','担当者が変更の理由を詳しく説明した。','たんとうしゃがへんこうのりゆうをくわしくせつめいした。','Tantousha ga henkou no riyuu o kuwashiku setsumei shita.','The person in charge explained the reason for the change in detail.','説明する makes information or reasons understandable.'),
('伝える','つたえる','tsutaeru','convey; tell','transitive verb','気持ちを伝える','感謝の気持ちを手紙で伝えました。','かんしゃのきもちをてがみでつたえました。','Kansha no kimochi o tegami de tsutaemashita.','I conveyed my gratitude in a letter.','伝える passes information or feelings to another person.'),
('知らせる','しらせる','shiraseru','inform; notify','transitive verb','結果を知らせる','試験の結果は来週メールで知らせます。','しけんのけっかはらいしゅうめーるでしらせます。','Shiken no kekka wa raishuu meeru de shirasemasu.','We will notify you of the test results by email next week.','知らせる emphasizes making someone aware of news or facts.'),
('相談する','そうだんする','soudan suru','consult','suru verb','先生に相談する','進路について両親と相談しています。','しんろについてりょうしんとそうだんしています。','Shinro ni tsuite ryoushin to soudan shite imasu.','I am consulting my parents about my future path.','相談する means seek advice or discuss a problem with someone.'),
('誘う','さそう','sasou','invite; ask along','transitive verb','友達を誘う','週末、友達を映画に誘った。','しゅうまつ、ともだちをえいがにさそった。','Shuumatsu, tomodachi o eiga ni sasotta.','I invited a friend to a movie this weekend.','誘う takes a person as を and an activity or destination as に.'),
('断る','ことわる','kotowaru','refuse; decline','transitive verb','誘いを断る','用事があったので、食事の誘いを断った。','ようじがあったので、しょくじのさそいをことわった。','Youji ga atta node, shokuji no sasoi o kotowatta.','I declined the invitation to eat because I had an errand.','断る means decline an offer or request; it can also mean give advance notice.'),
('頼む','たのむ','tanomu','request; ask','transitive verb','人に頼む','忙しい同僚に仕事を頼むのは気が引ける。','いそがしいどうりょうにしごとをたのむのはきがひける。','Isogashii douryou ni shigoto o tanomu no wa ki ga hikeru.','I feel hesitant about asking a busy colleague to do work.','頼む asks someone to do something; お願いする is its polite counterpart.'),
('許す','ゆるす','yurusu','forgive; permit','transitive verb','失敗を許す','彼は一度の失敗なら許してくれる。','かれはいちどのしっぱいならゆるしてくれる。','Kare wa ichido no shippai nara yurushite kureru.','He will forgive one mistake.','許す covers forgiving a person and permitting an action.'),
('謝る','あやまる','ayamaru','apologize','intransitive verb','相手に謝る','遅れたことを相手に謝りました。','おくれたことをあいてにあやまりました。','Okureta koto o aite ni ayamarimashita.','I apologized to the other person for being late.','謝る uses に for the person apologized to.'),
('賛成','さんせい','sansei','agreement; approval','noun/suru verb','提案に賛成する','私はその提案に賛成です。','わたしはそのていあんにさんせいです。','Watashi wa sono teian ni sansei desu.','I agree with that proposal.','賛成 takes に for the idea or proposal supported.'),
('反対','はんたい','hantai','opposition; contrary','noun/suru verb','計画に反対する','住民の多くが新しい計画に反対している。','じゅうみんのおおくがあたらしいけいかくにはんたいしている。','Juumin no ooku ga atarashii keikaku ni hantai shite iru.','Many residents oppose the new plan.','反対 means opposition or being contrary; 賛成 is its counterpart.'),
('反論','はんろん','hanron','counterargument','noun/suru verb','意見に反論する','彼はデータを示してその意見に反論した。','かれはでーたをしめしてそのいけんにはんろんした。','Kare wa deeta o shimeshite sono iken ni hanron shita.','He countered the opinion by presenting data.','反論 is a reasoned rebuttal, stronger than simply disagreeing.'),
('質問する','しつもんする','shitsumon suru','ask a question','suru verb','先生に質問する','分からない点があれば、遠慮なく質問してください。','わからないてんがあれば、えんりょなくしつもんしてください。','Wakaranai ten ga areba, enryo naku shitsumon shite kudasai.','If anything is unclear, please ask without hesitation.','質問する is ask a question; 尋ねる can also mean inquire or visit.'),
('答える','こたえる','kotaeru','answer','intransitive verb','質問に答える','学生は先生の質問に正しく答えた。','がくせいはせんせいのしつもんにただしくこたえた。','Gakusei wa sensei no shitsumon ni tadashiku kotaeta.','The student answered the teacher’s question correctly.','答える takes に for the question or request answered.'),
('返す','かえす','kaesu','return; give back','transitive verb','本を返す','図書館の本は金曜日までに返してください。','としょかんのほんはきんようびまでにかえしてください。','Toshokan no hon wa kinyoubi made ni kaeshite kudasai.','Please return the library book by Friday.','返す returns a thing; 返事を返す is possible but 返事をする is more natural.'),
('黙る','だまる','damaru','keep silent','intransitive verb','黙って聞く','まず黙って相手の話を聞きましょう。','まずだまってあいてのはなしをききましょう。','Mazu damatte aite no hanashi o kikimashou.','First, let’s listen to the other person silently.','黙る means become or remain silent; 黙って can mean without speaking.'),
('叫ぶ','さけぶ','sakebu','shout','intransitive verb','助けを叫ぶ','彼は大声で助けを叫んだ。','かれはおおごえでたすけをさけんだ。','Kare wa oogoe de tasuke o sakenda.','He shouted for help loudly.','叫ぶ is shout or cry out, often because of fear or urgency.'),
('声','こえ','koe','voice','noun','声が聞こえる','隣の部屋から母の声が聞こえた。','となりのへやからははのこえがきこえた。','Tonari no heya kara haha no koe ga kikoeta.','I heard my mother’s voice from the next room.','声 means a person’s voice or a figurative public opinion.'),
('口調','くちょう','kuchou','tone of voice','noun','口調が強い','彼の口調が急に強くなった。','かれのくちょうがきゅうにつよくなった。','Kare no kuchou ga kyuu ni tsuyoku natta.','His tone of voice suddenly became harsh.','口調 describes how words sound, including politeness or harshness.'),
('表情','ひょうじょう','hyoujou','facial expression','noun','表情を変える','知らせを聞いて、彼女の表情が変わった。','しらせをきいて、かのじょのひょうじょうがかわった。','Shirase o kiite, kanojo no hyoujou ga kawatta.','Her facial expression changed when she heard the news.','表情 is visible emotion on the face.'),
('態度','たいど','taido','attitude; manner','noun','態度を改める','注意されたら、少し態度を改めなさい。','ちゅういされたら、すこしたいどをあらためなさい。','Chuui saretara, sukoshi taido o aratamenasai.','If you are cautioned, improve your attitude a little.','態度 is behavior or manner toward people or situations.'),
('冗談','じょうだん','joudan','joke','noun','冗談を言う','冗談を言っただけなので、怒らないでください。','じょうだんをいっただけなので、おこらないでください。','Joudan o itta dake nanode, okoranaide kudasai.','I was only joking, so please do not get angry.','冗談を言う means tell a joke or make a joking remark.'),
('本音','ほんね','honne','true feelings','noun','本音を話す','友人には本音を話すことができます。','ゆうじんにはほんねをはなすことができます。','Yuujin ni wa honne o hanasu koto ga dekimasu.','I can speak my true feelings to my friends.','本音 is what one really thinks or feels, contrasted with 建前.'),
('建前','たてまえ','tatemae','public stance','noun','建前を述べる','会議では建前だけでなく、本音も必要だ。','かいぎではたてまえだけでなく、ほんねもひつようだ。','Kaigi de wa tatemae dake de naku, honne mo hitsuyou da.','At meetings, we need true opinions as well as the official stance.','建前 is the socially presentable position, contrasted with 本音.'),
('誤解','ごかい','gokai','misunderstanding','noun/suru verb','誤解を招く','説明が足りず、誤解を招いてしまった。','せつめいがたりず、ごかいをまねいてしまった。','Setsumei ga tarizu, gokai o maneite shimatta.','The insufficient explanation caused a misunderstanding.','誤解を招く means cause a misunderstanding; 誤解する means misunderstand.'),
]),
14:('Relationships','Vocabulary for family, friendship, trust, support, invitations, and interpersonal ties.',[
('友人','ゆうじん','yuujin','friend','noun','友人を訪ねる','週末、大学時代の友人を訪ねた。','しゅうまつ、だいがくじだいのゆうじんをたずねた。','Shuumatsu, daigaku jidai no yuujin o tazuneta.','I visited a friend from my university days this weekend.','友人 is a somewhat formal word for friend; 友達 is more casual.'),
('仲間','なかま','nakama','companion; fellow member','noun','仲間と協力する','同じ目標を持つ仲間と練習している。','おなじもくひょうをもつなかまとれんしゅうしている。','Onaji mokuhyou o motsu nakama to renshuu shite iru.','I practice with companions who share the same goal.','仲間 emphasizes belonging to the same group or activity.'),
('知り合い','しりあい','shiriai','acquaintance','noun','知り合いになる','旅行先で知り合いになった人から連絡が来た。','りょこうさきでしりあいになったひとかられんらくがきた。','Ryokousaki de shiriai ni natta hito kara renraku ga kita.','I heard from someone I got acquainted with while traveling.','知り合い is someone one knows but is not necessarily close to.'),
('家族','かぞく','kazoku','family','noun','家族と暮らす','卒業後もしばらく家族と暮らす予定です。','そつぎょうごもしばらくかぞくとくらすよていです。','Sotsugyougo mo shibaraku kazoku to kurasu yotei desu.','I plan to live with my family for a while after graduating.','家族 refers to the family unit or one’s family members.'),
('親戚','しんせき','shinseki','relative','noun','親戚が集まる','お正月には親戚が祖父母の家に集まる。','おしょうがつにはしんせきがそふぼのいえにあつまる。','Oshougatsu ni wa shinseki ga sofubo no ie ni atsumaru.','Relatives gather at my grandparents’ house during New Year.','親戚 means relatives beyond the immediate family.'),
('夫婦','ふうふ','fuufu','married couple','noun','夫婦で旅行する','その夫婦は毎年同じ温泉へ旅行する。','そのふうふはまいとしおなじおんせんへりょこうする。','Sono fuufu wa maitoshi onaji onsen e ryokou suru.','That married couple travels to the same hot spring every year.','夫婦 refers to a husband and wife as a pair.'),
('夫','おっと','otto','husband','noun','夫に相談する','妻は大切なことを夫に相談した。','つまはたいせつなことをおっとにそうだんした。','Tsuma wa taisetsu na koto o otto ni soudan shita.','The wife consulted her husband about an important matter.','夫 is the speaker’s own husband; 主人 is another common term.'),
('妻','つま','tsuma','wife','noun','妻を迎えに行く','仕事の帰りに妻を駅まで迎えに行った。','しごとのかえりにつまをえきまでむかえにいった。','Shigoto no kaeri ni tsuma o eki made mukae ni itta.','On my way home from work, I went to pick up my wife at the station.','妻 is the speaker’s own wife.'),
('親子','おやこ','oyako','parent and child','noun','親子で参加する','今日は親子で参加できる料理教室です。','きょうはおやこでさんかできるりょうりきょうしつです。','Kyou wa oyako de sanka dekiru ryouri kyoushitsu desu.','Today’s cooking class can be attended by parents and children together.','親子 treats parent and child as a pair.'),
('子供','こども','kodomo','child','noun','子供を育てる','地域全体で子供を育てることが大切です。','ちいきぜんたいでこどもをそだてることがたいせつです。','Chiiki zentai de kodomo o sodateru koto ga taisetsu desu.','It is important for the whole community to raise children.','子供 means child or children; 子ども is a common modern spelling.'),
('隣人','りんじん','rinjin','neighbor','noun','隣人に挨拶する','引っ越した日に隣人へ挨拶に行った。','ひっこしたひにりんじんへあいさつにいった。','Hikkoshita hi ni rinjin e aisatsu ni itta.','I went to greet my neighbors on the day I moved in.','隣人 is a neighbor, somewhat more formal than 隣の人.'),
('先輩','せんぱい','senpai','senior; older colleague','noun','先輩に教わる','職場の先輩に仕事の進め方を教わった。','しょくばのせんぱいにしごとのすすめかたをおそわった。','Shokuba no senpai ni shigoto no susumekata o osowatta.','I learned how to proceed with the work from a senior colleague.','先輩 is someone senior by school year, experience, or organizational standing.'),
('後輩','こうはい','kouhai','junior; younger colleague','noun','後輩を助ける','困っている後輩の相談に乗った。','こまっているこうはいのそうだんにのった。','Komatte iru kouhai no soudan ni notta.','I listened to a junior colleague’s worries.','後輩 is someone junior in a school or organization.'),
('出会い','であい','deai','encounter; meeting','noun','出会いを大切にする','旅先での出会いが人生を変えることもある。','たびさきでのであいがじんせいをかえることもある。','Tabisaki de no deai ga jinsei o kaeru koto mo aru.','Encounters while traveling can sometimes change one’s life.','出会い emphasizes the event of meeting someone.'),
('付き合う','つきあう','tsukiau','associate; date','intransitive verb','人と付き合う','無理をせず、信頼できる人と付き合いたい。','むりをせず、しんらいできるひととつきあいたい。','Muri o sezu, shinrai dekiru hito to tsukiaitai.','I want to associate with people I can trust without forcing things.','付き合う means associate with or date, depending on context.'),
('別れる','わかれる','wakareru','separate; part','intransitive verb','友人と別れる','駅で友人と別れて、家へ帰った。','えきでゆうじんとわかれて、いえへかえった。','Eki de yuujin to wakarete, ie e kaetta.','I parted from my friend at the station and went home.','別れる means part from someone or end a romantic relationship.'),
('信頼','しんらい','shinrai','trust','noun/suru verb','信頼を得る','約束を守ることで、相手の信頼を得た。','やくそくをまもることで、あいてのしんらいをえた。','Yakusoku o mamoru koto de, aite no shinrai o eta.','By keeping my promise, I earned the other person’s trust.','信頼 is confidence in a person’s reliability.'),
('尊敬','そんけい','sonkei','respect','noun/suru verb','人を尊敬する','私は努力を続ける母を尊敬しています。','わたしはどりょくをつづけるははをそんけいしています。','Watashi wa doryoku o tsuzukeru haha o sonkei shite imasu.','I respect my mother for continuing to work hard.','尊敬する expresses admiration and respect for a person.'),
('協力','きょうりょく','kyouryoku','cooperation','noun/suru verb','協力を求める','引っ越しのために友人の協力を求めた。','ひっこしのためにゆうじんのきょうりょくをもとめた。','Hikkoshi no tame ni yuujin no kyouryoku o motometa.','I asked my friends for help with the move.','協力 is working together toward a shared goal.'),
('仲良し','なかよし','nakayoshi','close friend; friendly','noun/な-adjective','仲良しになる','二人は小学校からの仲良しです。','ふたりはしょうがっこうからのなかよしです。','Futari wa shougakkou kara no nakayoshi desu.','The two have been close friends since elementary school.','仲良し describes people who are especially close and friendly.'),
('親しい','したしい','shitashii','close; familiar','い-adjective','親しい友人','親しい友人にだけ悩みを打ち明けた。','したしいゆうじんにだけなやみをうちあけた。','Shitashii yuujin ni dake nayami o uchiaketa.','I confided my worries only to a close friend.','親しい means emotionally close or familiar, not merely acquainted.'),
('親切','しんせつ','shinsetsu','kind; kindness','な-adjective/noun','親切にする','道に迷った観光客に親切に道を教えた。','みちにまよったかんこうきゃくにしんせつにみちをおしえた。','Michi ni mayotta kankoukyaku ni shinsetsu ni michi o oshieta.','I kindly showed a lost tourist the way.','親切な describes kindness; 親切にする means treat someone kindly.'),
('世話','せわ','sewa','care; help','noun/suru verb','世話になる','留学中、ホストファミリーに世話になった。','りゅうがくちゅう、ほすとふぁみりーにせわになった。','Ryuugakuchuu, hosuto famirii ni sewa ni natta.','While studying abroad, I received care from my host family.','世話になる means receive help or care; 世話をする means care for someone.'),
('迷惑','めいわく','meiwaku','trouble; nuisance','noun/suru verb','迷惑をかける','夜遅くに大きな音を出すと、隣人に迷惑をかける。','よるおそくにおおきなおとをだすと、りんじんにめいわくをかける。','Yoru osoku ni ookina oto o dasu to, rinjin ni meiwaku o kakeru.','Making loud noises late at night causes trouble for the neighbors.','迷惑をかける means inconvenience or trouble someone.'),
('紹介','しょうかい','shoukai','introduction','noun/suru verb','友人を紹介する','来週、職場の友人を家族に紹介します。','らいしゅう、しょくばのゆうじんをかぞくにしょうかいします。','Raishuu, shokuba no yuujin o kazoku ni shoukai shimasu.','Next week I will introduce a workplace friend to my family.','紹介する introduces a person, place, or information.'),
('招待','しょうたい','shoutai','invitation','noun/suru verb','パーティーに招待する','新しい家のパーティーに近所の人を招待した。','あたらしいいえのぱーてぃーにきんじょのひとをしょうたいした。','Atarashii ie no paatii ni kinjo no hito o shoutai shita.','I invited the neighbors to a party at my new house.','招待する is a deliberate invitation to an event or place.'),
('歓迎','かんげい','kangei','welcome','noun/suru verb','新しい仲間を歓迎する','みんなで新しい仲間を歓迎した。','みんなであたらしいなかまをかんげいした。','Minna de atarashii nakama o kangei shita.','Everyone welcomed the new member.','歓迎する means warmly welcome someone or something.'),
('約束を守る','やくそくをまもる','yakusoku o mamoru','keep a promise','verb phrase','約束を守る','信頼される人は、どんな小さな約束も守る。','しんらいされるひとは、どんなちいさなやくそくもまもる。','Shinrai sareru hito wa, donna chiisana yakusoku mo mamoru.','A trusted person keeps even the smallest promise.','約束を守る means keep a promise; 約束を破る is break one.'),
('助け合う','たすけあう','tasukeau','help each other','う-verb','互いに助け合う','家族は困ったときに互いに助け合うものです。','かぞくはこまったときにたがいにたすけあうものです。','Kazoku wa komatta toki ni tagai ni tasukeau mono desu.','Families are meant to help one another when there is trouble.','助け合う expresses reciprocal help.'),
('仲直り','なかなおり','nakanaori','reconciliation','noun/suru verb','仲直りする','二人は話し合って、すぐに仲直りした。','ふたりははなしあって、すぐになかなおりした。','Futari wa hanashiatte, sugu ni nakanaori shita.','The two talked and made up quickly.','仲直りする means restore a friendly relationship after a quarrel.'),
('関係','かんけい','kankei','relationship; connection','noun','関係を築く','時間をかけて相手との信頼関係を築いた。','じかんをかけてあいてとのしんらいかんけいをきずいた。','Jikan o kakete aite to no shinrai kankei o kizuita.','I built a relationship of trust with the other person over time.','関係 is a relationship or connection between people or things.'),
('相手','あいて','aite','other person; opponent','noun','相手の立場を考える','話す前に、相手の立場を考えましょう。','はなすまえに、あいてのたちばをかんがえましょう。','Hanasu mae ni, aite no tachiba o kangaemashou.','Before speaking, let’s consider the other person’s position.','相手 means the person one is dealing with, or an opponent in a contest.'),
]),
}

def make(lid):
    title,overview,rows=L[lid]
    items=[]
    for x in rows:
        w,r,ro,m,p,u,e,er,rom,tr,n=x
        items.append(item(w,r,ro,m,p,u,e,er,(rom,tr),n))
    ex=[
      {'type':'meaning','question':f'What does {rows[0][0]} mean?','options':[rows[0][3],rows[1][3],'salary','vacation'],'answer':rows[0][3],'explanation':f'{rows[0][0]} means {rows[0][3]}.'},
      {'type':'reading','question':f'Choose the reading for {rows[4][0]}.','options':[rows[4][1],rows[5][1],rows[6][1],rows[7][1]],'answer':rows[4][1],'explanation':f'{rows[4][0]} is read {rows[4][1]}.'},
      {'type':'collocation','question':f'Which phrase naturally completes: {rows[8][0]}を＿＿。','options':['受ける','食べる','泳ぐ','赤い'],'answer':'受ける','explanation':f'{rows[8][0]}を受ける is the natural collocation.'},
      {'type':'translation','question':f'Translate: {rows[10][6]}','answer':rows[10][9],'explanation':f'{rows[10][0]} means {rows[10][3]} in this sentence.'},
      {'type':'particle','question':('会社＿＿勤める。' if lid==11 else '本社＿＿確認する。' if lid==12 else '先生＿＿質問する。' if lid==13 else '友人＿＿相談する。'),'options':['に','を','が','で'],'answer':'に','explanation':'The destination or person involved takes に in this pattern.'},
      {'type':'contrast','question':f'Which word means {rows[-1][3]}?','options':[rows[-1][0],rows[-2][0],rows[0][0],rows[1][0]],'answer':rows[-1][0],'explanation':f'{rows[-1][0]} means {rows[-1][3]}.'}
    ]
    return {'id':lid,'title':title,'overview':overview,'items':items,'exercises':ex}

for lid in L:
    with open(f'content/vocab_{lid}.json','w',encoding='utf-8') as f: json.dump(make(lid),f,ensure_ascii=False,indent=2)
